  final double? _DURATION;
  final double? _STEP;
  final int? _OUTPUT_POINTS;
  final bool? _STATE_TRANSITION;

  tbpPropagationRequestObjectBuilder({
    tbpStateObjectBuilder? INITIAL_STATE,
    tbpStateObjectBuilder? initialState,
    double? DURATION,
    double? STEP,
    int? OUTPUT_POINTS,
    int? outputPoints,
    bool? STATE_TRANSITION,
    bool? stateTransition,
  })
      : _INITIAL_STATE = initialState ?? INITIAL_STATE,
        _DURATION = DURATION,
        _STEP = STEP,
        _OUTPUT_POINTS = outputPoints ?? OUTPUT_POINTS,
        _STATE_TRANSITION = stateTransition ?? STATE_TRANSITION;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? INITIAL_STATEOffset = _INITIAL_STATE?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(5);
    fbBuilder.addOffset(0, INITIAL_STATEOffset);
    fbBuilder.addFloat64(1, _DURATION);
    fbBuilder.addFloat64(2, _STEP);
    fbBuilder.addUint32(3, _OUTPUT_POINTS);
    fbBuilder.addBool(4, _STATE_TRANSITION);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
///  A transfer into the system.
class tbpTransfer {
  tbpTransfer._(this._bc, this._bcOffset);
  factory tbpTransfer(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<tbpTransfer> reader = _tbpTransferReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  tbpTransferKind get KIND => tbpTransferKind.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 4, 0));
  ///  Altitude of the circular parking orbit about the larger primary, km.
  double get PARKING_ALTITUDE_KM => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 6, 0.0);
  double get parkingAltitudeKm => PARKING_ALTITUDE_KM;
  ///  Altitude of the final orbit about the smaller primary, km.
  double get TARGET_ALTITUDE_KM => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 8, 0.0);
  double get targetAltitudeKm => TARGET_ALTITUDE_KM;
  ///  Inclination of the transfer plane, deg.
  double get INCLINATION_DEG => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 10, 0.0);
  double get inclinationDeg => INCLINATION_DEG;
  ///  PeriodicOrbitInsertion: the orbit to insert into.
  tbpPeriodicOrbit? get TARGET_ORBIT => tbpPeriodicOrbit.reader.vTableGetNullable(_bc, _bcOffset, 12);
  tbpPeriodicOrbit? get targetOrbit => TARGET_ORBIT;
  ///  Targeter limits; 0 = default.
  int get MAX_ITERATIONS => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 14, 0);
  int get maxIterations => MAX_ITERATIONS;
  double get TOLERANCE => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 16, 0.0);
  ///  Result: convergence of the targeter.
  bool get CONVERGED => const fb.BoolReader().vTableGet(_bc, _bcOffset, 18, false);
  ///  Result: departure and arrival burns (their DELTA_V in the axes they
  ///  state, km/s; offsets in seconds from departure).
  List<mplBurn>? get BURNS => const fb.ListReader<mplBurn>(mplBurn.reader).vTableGetNullable(_bc, _bcOffset, 20);
  ///  Result: total delta-v, km/s, and time of flight, s.
  double get TOTAL_DELTA_V_KM_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 22, 0.0);
  double get totalDeltaVKmS => TOTAL_DELTA_V_KM_S;
  double get TIME_OF_FLIGHT_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 24, 0.0);
  double get timeOfFlightS => TIME_OF_FLIGHT_S;
  ///  Result: the transfer trajectory; empty = not sampled.
  tbpTrajectory? get TRAJECTORY => tbpTrajectory.reader.vTableGetNullable(_bc, _bcOffset, 26);

  @override
  String toString() {
    return 'tbpTransfer{KIND: ${KIND}, parkingAltitudeKm: ${parkingAltitudeKm}, targetAltitudeKm: ${targetAltitudeKm}, inclinationDeg: ${inclinationDeg}, targetOrbit: ${targetOrbit}, maxIterations: ${maxIterations}, TOLERANCE: ${TOLERANCE}, CONVERGED: ${CONVERGED}, BURNS: ${BURNS}, totalDeltaVKmS: ${totalDeltaVKmS}, timeOfFlightS: ${timeOfFlightS}, TRAJECTORY: ${TRAJECTORY}}';
  }
}

class _tbpTransferReader extends fb.TableReader<tbpTransfer> {
  const _tbpTransferReader();

  @override
  tbpTransfer createObject(fb.BufferContext bc, int offset) =>
    tbpTransfer._(bc, offset);
}

class tbpTransferBuilder {
  tbpTransferBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(12);
  }

  int addKind(tbpTransferKind? KIND) {
    fbBuilder.addUint8(0, KIND?.value);
    return fbBuilder.offset;
  }
  int addParkingAltitudeKm(double? PARKING_ALTITUDE_KM) {
    fbBuilder.addFloat64(1, PARKING_ALTITUDE_KM);
    return fbBuilder.offset;
  }
  int addTargetAltitudeKm(double? TARGET_ALTITUDE_KM) {
    fbBuilder.addFloat64(2, TARGET_ALTITUDE_KM);
    return fbBuilder.offset;
  }
  int addInclinationDeg(double? INCLINATION_DEG) {
    fbBuilder.addFloat64(3, INCLINATION_DEG);
    return fbBuilder.offset;
  }
  int addTargetOrbitOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addMaxIterations(int? MAX_ITERATIONS) {
    fbBuilder.addUint32(5, MAX_ITERATIONS);
    return fbBuilder.offset;
  }
  int addTolerance(double? TOLERANCE) {
    fbBuilder.addFloat64(6, TOLERANCE);
    return fbBuilder.offset;
  }
  int addConverged(bool? CONVERGED) {
    fbBuilder.addBool(7, CONVERGED);
    return fbBuilder.offset;
  }
  int addBurnsOffset(int? offset) {
    fbBuilder.addOffset(8, offset);
    return fbBuilder.offset;
  }
  int addTotalDeltaVKmS(double? TOTAL_DELTA_V_KM_S) {
    fbBuilder.addFloat64(9, TOTAL_DELTA_V_KM_S);
    return fbBuilder.offset;
  }
  int addTimeOfFlightS(double? TIME_OF_FLIGHT_S) {
    fbBuilder.addFloat64(10, TIME_OF_FLIGHT_S);
    return fbBuilder.offset;
  }
  int addTrajectoryOffset(int? offset) {
    fbBuilder.addOffset(11, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class tbpTransferObjectBuilder extends fb.ObjectBuilder {
  final tbpTransferKind? _KIND;
  final double? _PARKING_ALTITUDE_KM;
  final double? _TARGET_ALTITUDE_KM;
  final double? _INCLINATION_DEG;
  final tbpPeriodicOrbitObjectBuilder? _TARGET_ORBIT;
  final int? _MAX_ITERATIONS;
  final double? _TOLERANCE;
  final bool? _CONVERGED;
  final List<mplBurnObjectBuilder>? _BURNS;
  final double? _TOTAL_DELTA_V_KM_S;
  final double? _TIME_OF_FLIGHT_S;
  final tbpTrajectoryObjectBuilder? _TRAJECTORY;

  tbpTransferObjectBuilder({
    tbpTransferKind? KIND,
    double? PARKING_ALTITUDE_KM,
    double? parkingAltitudeKm,
    double? TARGET_ALTITUDE_KM,
    double? targetAltitudeKm,
    double? INCLINATION_DEG,
    double? inclinationDeg,
    tbpPeriodicOrbitObjectBuilder? TARGET_ORBIT,
    tbpPeriodicOrbitObjectBuilder? targetOrbit,
    int? MAX_ITERATIONS,
    int? maxIterations,
    double? TOLERANCE,
    bool? CONVERGED,
    List<mplBurnObjectBuilder>? BURNS,
    double? TOTAL_DELTA_V_KM_S,
    double? totalDeltaVKmS,
    double? TIME_OF_FLIGHT_S,
    double? timeOfFlightS,
    tbpTrajectoryObjectBuilder? TRAJECTORY,
  })
      : _KIND = KIND,
        _PARKING_ALTITUDE_KM = parkingAltitudeKm ?? PARKING_ALTITUDE_KM,
        _TARGET_ALTITUDE_KM = targetAltitudeKm ?? TARGET_ALTITUDE_KM,
        _INCLINATION_DEG = inclinationDeg ?? INCLINATION_DEG,
        _TARGET_ORBIT = targetOrbit ?? TARGET_ORBIT,
        _MAX_ITERATIONS = maxIterations ?? MAX_ITERATIONS,
        _TOLERANCE = TOLERANCE,
        _CONVERGED = CONVERGED,
        _BURNS = BURNS,
        _TOTAL_DELTA_V_KM_S = totalDeltaVKmS ?? TOTAL_DELTA_V_KM_S,
        _TIME_OF_FLIGHT_S = timeOfFlightS ?? TIME_OF_FLIGHT_S,
        _TRAJECTORY = TRAJECTORY;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? TARGET_ORBITOffset = _TARGET_ORBIT?.getOrCreateOffset(fbBuilder);
    final int? BURNSOffset = _BURNS == null ? null
        : fbBuilder.writeList(_BURNS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? TRAJECTORYOffset = _TRAJECTORY?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(12);
    fbBuilder.addUint8(0, _KIND?.value);
    fbBuilder.addFloat64(1, _PARKING_ALTITUDE_KM);
    fbBuilder.addFloat64(2, _TARGET_ALTITUDE_KM);
    fbBuilder.addFloat64(3, _INCLINATION_DEG);
    fbBuilder.addOffset(4, TARGET_ORBITOffset);
    fbBuilder.addUint32(5, _MAX_ITERATIONS);
    fbBuilder.addFloat64(6, _TOLERANCE);
    fbBuilder.addBool(7, _CONVERGED);
    fbBuilder.addOffset(8, BURNSOffset);
    fbBuilder.addFloat64(9, _TOTAL_DELTA_V_KM_S);
    fbBuilder.addFloat64(10, _TIME_OF_FLIGHT_S);
    fbBuilder.addOffset(11, TRAJECTORYOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
///  Station-keeping budget for a periodic orbit.
class tbpStationKeeping {
  tbpStationKeeping._(this._bc, this._bcOffset);
  factory tbpStationKeeping(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<tbpStationKeeping> reader = _tbpStationKeepingReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  The orbit kept (its INITIAL_STATE, PERIOD and JACOBI at least).
  tbpPeriodicOrbit? get ORBIT => tbpPeriodicOrbit.reader.vTableGetNullable(_bc, _bcOffset, 4);
  tbpStationKeepingStrategy get STRATEGY => tbpStationKeepingStrategy.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 6, 0));
  ///  Navigation (orbit knowledge) error, km, 1 sigma.
  double get NAVIGATION_ERROR_KM => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 8, 0.0);
  double get navigationErrorKm => NAVIGATION_ERROR_KM;
  ///  Maneuver execution error, fraction of each burn, 1 sigma.
  double get EXECUTION_ERROR_FRACTION => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 10, 0.0);
  double get executionErrorFraction => EXECUTION_ERROR_FRACTION;
  ///  Station-keeping cycles simulated.
  int get CYCLES => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 12, 0);
  ///  Result: delta-v per year, km/s.
  double get ANNUAL_DELTA_V_KM_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 14, 0.0);
  double get annualDeltaVKmS => ANNUAL_DELTA_V_KM_S;
  ///  Result: mean and largest delta-v per cycle, km/s.
  double get MEAN_CYCLE_DELTA_V_KM_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 16, 0.0);
  double get meanCycleDeltaVKmS => MEAN_CYCLE_DELTA_V_KM_S;
  double get MAX_CYCLE_DELTA_V_KM_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 18, 0.0);
  double get maxCycleDeltaVKmS => MAX_CYCLE_DELTA_V_KM_S;
  ///  Result: delta-v of each cycle, km/s.
  List<double>? get CYCLE_DELTA_V_KM_S => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 20);
  List<double>? get cycleDeltaVKmS => CYCLE_DELTA_V_KM_S;
  ///  Result: true when the orbit stays bounded over the simulation.
  bool get BOUNDED => const fb.BoolReader().vTableGet(_bc, _bcOffset, 22, false);

  @override
  String toString() {
    return 'tbpStationKeeping{ORBIT: ${ORBIT}, STRATEGY: ${STRATEGY}, navigationErrorKm: ${navigationErrorKm}, executionErrorFraction: ${executionErrorFraction}, CYCLES: ${CYCLES}, annualDeltaVKmS: ${annualDeltaVKmS}, meanCycleDeltaVKmS: ${meanCycleDeltaVKmS}, maxCycleDeltaVKmS: ${maxCycleDeltaVKmS}, cycleDeltaVKmS: ${cycleDeltaVKmS}, BOUNDED: ${BOUNDED}}';
  }
