///  A state converted between the synodic and inertial frames. The inertial
///  frame is centred on the barycentre with its X axis along the synodic X
///  axis at REFERENCE_EPOCH_MS (elapsed time 0) and Z along the system's
///  angular momentum.
class tbpFrameConversion {
  tbpFrameConversion._(this._bc, this._bcOffset);
  factory tbpFrameConversion(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<tbpFrameConversion> reader = _tbpFrameConversionReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  tbpConversionDirection get DIRECTION => tbpConversionDirection.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 4, 0));
  ///  Unix milliseconds when the two frames are aligned; 0 = relative time
  ///  only.
  int get REFERENCE_EPOCH_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 6, 0);
  int get referenceEpochMs => REFERENCE_EPOCH_MS;
  ///  Seconds from the alignment to the state.
  double get ELAPSED_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 8, 0.0);
  double get elapsedS => ELAPSED_S;
  ///  The synodic state (input or result), non-dimensional.
  tbpState? get SYNODIC => tbpState.reader.vTableGetNullable(_bc, _bcOffset, 10);
  ///  The inertial state (input or result): km and km/s, 6 values.
  List<double>? get INERTIAL => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 12);

  @override
  String toString() {
    return 'tbpFrameConversion{DIRECTION: ${DIRECTION}, referenceEpochMs: ${referenceEpochMs}, elapsedS: ${elapsedS}, SYNODIC: ${SYNODIC}, INERTIAL: ${INERTIAL}}';
  }
}

