///  Three-Body Problem - a CR3BP system and one answer about it.
class TBP {
  TBP._(this._bc, this._bcOffset);
  factory TBP(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<TBP> reader = _TBPReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Identifier of the record; empty = not assigned.
  String? get ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  Unix milliseconds the record was produced.
  int get CREATED_AT_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 6, 0);
  int get createdAtMs => CREATED_AT_MS;
  ///  Identifier of the producing service or tool.
  String? get PRODUCER => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 8);
  tbpProblem get PROBLEM => tbpProblem.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 10, 0));
  tbpSystem? get SYSTEM => tbpSystem.reader.vTableGetNullable(_bc, _bcOffset, 12);
  tbpStatus get STATUS => tbpStatus.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 14, 0));
  ///  Stable machine-readable reason when STATUS is not Solved.
  String? get ERROR_CODE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 16);
  String? get errorCode => ERROR_CODE;
  String? get ERROR_MESSAGE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 18);
  String? get errorMessage => ERROR_MESSAGE;
  ///  Propagation: the request, and the propagated trajectory.
  tbpPropagationRequest? get PROPAGATION => tbpPropagationRequest.reader.vTableGetNullable(_bc, _bcOffset, 20);
  tbpTrajectory? get TRAJECTORY => tbpTrajectory.reader.vTableGetNullable(_bc, _bcOffset, 22);
  ///  LibrationPoints: L1 to L5.
  List<tbpLibrationPoint>? get LIBRATION_POINTS => const fb.ListReader<tbpLibrationPoint>(tbpLibrationPoint.reader).vTableGetNullable(_bc, _bcOffset, 24);
  List<tbpLibrationPoint>? get librationPoints => LIBRATION_POINTS;
  ///  JacobiConstant: the state, and its Jacobi constant.
  tbpState? get STATE => tbpState.reader.vTableGetNullable(_bc, _bcOffset, 26);
  double get JACOBI => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 28, 0.0);
  ///  PeriodicOrbit, HaloFirstGuess, NearRectilinearHalo: the request fields
  ///  (FAMILY, LIBRATION_POINT, AMPLITUDE or perilune/apolune, TOLERANCE,
  ///  MAX_ITERATIONS) and the result. Family: the members, ordered along the
  ///  family's continuation parameter (AMPLITUDE).
  List<tbpPeriodicOrbit>? get ORBITS => const fb.ListReader<tbpPeriodicOrbit>(tbpPeriodicOrbit.reader).vTableGetNullable(_bc, _bcOffset, 30);
  tbpTransfer? get TRANSFER => tbpTransfer.reader.vTableGetNullable(_bc, _bcOffset, 32);
  tbpStationKeeping? get STATION_KEEPING => tbpStationKeeping.reader.vTableGetNullable(_bc, _bcOffset, 34);
  tbpStationKeeping? get stationKeeping => STATION_KEEPING;
  tbpFrameConversion? get FRAME_CONVERSION => tbpFrameConversion.reader.vTableGetNullable(_bc, _bcOffset, 36);
  tbpFrameConversion? get frameConversion => FRAME_CONVERSION;

  @override
  String toString() {
    return 'TBP{ID: ${ID}, createdAtMs: ${createdAtMs}, PRODUCER: ${PRODUCER}, PROBLEM: ${PROBLEM}, SYSTEM: ${SYSTEM}, STATUS: ${STATUS}, errorCode: ${errorCode}, errorMessage: ${errorMessage}, PROPAGATION: ${PROPAGATION}, TRAJECTORY: ${TRAJECTORY}, librationPoints: ${librationPoints}, STATE: ${STATE}, JACOBI: ${JACOBI}, ORBITS: ${ORBITS}, TRANSFER: ${TRANSFER}, stationKeeping: ${stationKeeping}, frameConversion: ${frameConversion}}';
  }
}

class _TBPReader extends fb.TableReader<TBP> {
  const _TBPReader();

  @override
  TBP createObject(fb.BufferContext bc, int offset) =>
    TBP._(bc, offset);
}

class TBPBuilder {
  TBPBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(17);
  }

  int addIdOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addCreatedAtMs(int? CREATED_AT_MS) {
    fbBuilder.addInt64(1, CREATED_AT_MS);
    return fbBuilder.offset;
  }
  int addProducerOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }
  int addProblem(tbpProblem? PROBLEM) {
    fbBuilder.addUint8(3, PROBLEM?.value);
    return fbBuilder.offset;
  }
  int addSystemOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addStatus(tbpStatus? STATUS) {
    fbBuilder.addUint8(5, STATUS?.value);
    return fbBuilder.offset;
  }
  int addErrorCodeOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addErrorMessageOffset(int? offset) {
    fbBuilder.addOffset(7, offset);
    return fbBuilder.offset;
  }
  int addPropagationOffset(int? offset) {
    fbBuilder.addOffset(8, offset);
    return fbBuilder.offset;
  }
  int addTrajectoryOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }
  int addLibrationPointsOffset(int? offset) {
    fbBuilder.addOffset(10, offset);
    return fbBuilder.offset;
  }
  int addStateOffset(int? offset) {
    fbBuilder.addOffset(11, offset);
    return fbBuilder.offset;
  }
  int addJacobi(double? JACOBI) {
    fbBuilder.addFloat64(12, JACOBI);
    return fbBuilder.offset;
  }
  int addOrbitsOffset(int? offset) {
    fbBuilder.addOffset(13, offset);
    return fbBuilder.offset;
  }
  int addTransferOffset(int? offset) {
    fbBuilder.addOffset(14, offset);
    return fbBuilder.offset;
  }
  int addStationKeepingOffset(int? offset) {
    fbBuilder.addOffset(15, offset);
    return fbBuilder.offset;
  }
  int addFrameConversionOffset(int? offset) {
    fbBuilder.addOffset(16, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class TBPObjectBuilder extends fb.ObjectBuilder {
  final String? _ID;
  final int? _CREATED_AT_MS;
  final String? _PRODUCER;
  final tbpProblem? _PROBLEM;
  final tbpSystemObjectBuilder? _SYSTEM;
  final tbpStatus? _STATUS;
  final String? _ERROR_CODE;
  final String? _ERROR_MESSAGE;
  final tbpPropagationRequestObjectBuilder? _PROPAGATION;
  final tbpTrajectoryObjectBuilder? _TRAJECTORY;
  final List<tbpLibrationPointObjectBuilder>? _LIBRATION_POINTS;
  final tbpStateObjectBuilder? _STATE;
  final double? _JACOBI;
  final List<tbpPeriodicOrbitObjectBuilder>? _ORBITS;
  final tbpTransferObjectBuilder? _TRANSFER;
  final tbpStationKeepingObjectBuilder? _STATION_KEEPING;
  final tbpFrameConversionObjectBuilder? _FRAME_CONVERSION;

  TBPObjectBuilder({
    String? ID,
    int? CREATED_AT_MS,
    int? createdAtMs,
    String? PRODUCER,
    tbpProblem? PROBLEM,
    tbpSystemObjectBuilder? SYSTEM,
    tbpStatus? STATUS,
    String? ERROR_CODE,
    String? errorCode,
    String? ERROR_MESSAGE,
    String? errorMessage,
    tbpPropagationRequestObjectBuilder? PROPAGATION,
    tbpTrajectoryObjectBuilder? TRAJECTORY,
    List<tbpLibrationPointObjectBuilder>? LIBRATION_POINTS,
    List<tbpLibrationPointObjectBuilder>? librationPoints,
    tbpStateObjectBuilder? STATE,
    double? JACOBI,
    List<tbpPeriodicOrbitObjectBuilder>? ORBITS,
    tbpTransferObjectBuilder? TRANSFER,
    tbpStationKeepingObjectBuilder? STATION_KEEPING,
    tbpStationKeepingObjectBuilder? stationKeeping,
    tbpFrameConversionObjectBuilder? FRAME_CONVERSION,
    tbpFrameConversionObjectBuilder? frameConversion,
  })
      : _ID = ID,
        _CREATED_AT_MS = createdAtMs ?? CREATED_AT_MS,
        _PRODUCER = PRODUCER,
        _PROBLEM = PROBLEM,
        _SYSTEM = SYSTEM,
        _STATUS = STATUS,
        _ERROR_CODE = errorCode ?? ERROR_CODE,
        _ERROR_MESSAGE = errorMessage ?? ERROR_MESSAGE,
        _PROPAGATION = PROPAGATION,
        _TRAJECTORY = TRAJECTORY,
        _LIBRATION_POINTS = librationPoints ?? LIBRATION_POINTS,
        _STATE = STATE,
        _JACOBI = JACOBI,
        _ORBITS = ORBITS,
        _TRANSFER = TRANSFER,
        _STATION_KEEPING = stationKeeping ?? STATION_KEEPING,
        _FRAME_CONVERSION = frameConversion ?? FRAME_CONVERSION;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? IDOffset = _ID == null ? null
        : fbBuilder.writeString(_ID!);
    final int? PRODUCEROffset = _PRODUCER == null ? null
        : fbBuilder.writeString(_PRODUCER!);
    final int? SYSTEMOffset = _SYSTEM?.getOrCreateOffset(fbBuilder);
    final int? ERROR_CODEOffset = _ERROR_CODE == null ? null
        : fbBuilder.writeString(_ERROR_CODE!);
    final int? ERROR_MESSAGEOffset = _ERROR_MESSAGE == null ? null
        : fbBuilder.writeString(_ERROR_MESSAGE!);
    final int? PROPAGATIONOffset = _PROPAGATION?.getOrCreateOffset(fbBuilder);
    final int? TRAJECTORYOffset = _TRAJECTORY?.getOrCreateOffset(fbBuilder);
    final int? LIBRATION_POINTSOffset = _LIBRATION_POINTS == null ? null
        : fbBuilder.writeList(_LIBRATION_POINTS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? STATEOffset = _STATE?.getOrCreateOffset(fbBuilder);
    final int? ORBITSOffset = _ORBITS == null ? null
        : fbBuilder.writeList(_ORBITS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? TRANSFEROffset = _TRANSFER?.getOrCreateOffset(fbBuilder);
    final int? STATION_KEEPINGOffset = _STATION_KEEPING?.getOrCreateOffset(fbBuilder);
    final int? FRAME_CONVERSIONOffset = _FRAME_CONVERSION?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(17);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addInt64(1, _CREATED_AT_MS);
    fbBuilder.addOffset(2, PRODUCEROffset);
    fbBuilder.addUint8(3, _PROBLEM?.value);
    fbBuilder.addOffset(4, SYSTEMOffset);
    fbBuilder.addUint8(5, _STATUS?.value);
    fbBuilder.addOffset(6, ERROR_CODEOffset);
    fbBuilder.addOffset(7, ERROR_MESSAGEOffset);
    fbBuilder.addOffset(8, PROPAGATIONOffset);
    fbBuilder.addOffset(9, TRAJECTORYOffset);
    fbBuilder.addOffset(10, LIBRATION_POINTSOffset);
    fbBuilder.addOffset(11, STATEOffset);
    fbBuilder.addFloat64(12, _JACOBI);
    fbBuilder.addOffset(13, ORBITSOffset);
    fbBuilder.addOffset(14, TRANSFEROffset);
    fbBuilder.addOffset(15, STATION_KEEPINGOffset);
    fbBuilder.addOffset(16, FRAME_CONVERSIONOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
